// Merge Two Sorted Lists into one sorted list
let list1 = AnimatedLinkedList<Int>()
let list2 = AnimatedLinkedList<Int>()
list1.append(1)
list1.append(3)
list1.append(5)
list2.append(2)
list2.append(4)
list2.append(6)

func mergeSortedLists(_ l1: AnimatedLinkedList<Int>, _ l2: AnimatedLinkedList<Int>) -> AnimatedLinkedList<Int> {
    let result = AnimatedLinkedList<Int>()
    while !l1.isEmpty || !l2.isEmpty {
        if l1.isEmpty {
            if let val = l2.remove(at: 0) {
                result.append(val)
            }
        } else if l2.isEmpty {
            if let val = l1.remove(at: 0) {
                result.append(val)
            }
        } else {
            let val1 = l1.remove(at: 0)
            let val2 = l2.remove(at: 0)
            if let v1 = val1, let v2 = val2 {
                if v1 <= v2 {
                    result.append(v1)
                    l2.prepend(v2)
                } else {
                    result.append(v2)
                    l1.prepend(v1)
                }
            }
        }
    }
    return result
}

let merged = mergeSortedLists(list1, list2)
